1420	Result<WriteResults> CollectionImpl::write_impl(std::vector<Doc> &docs,
1421	                                                WriteMode mode) {
1422	  CHECK_READONLY_RETURN_STATUS_EXPECTED();
1423	
1424	  std::shared_lock lock(schema_handle_mtx_);
1425	
1426	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1427	
1428	  for (auto &&doc : docs) {
1429	    auto s = doc.validate_and_sanitize(schema_, mode == WriteMode::UPDATE);
1430	    CHECK_RETURN_STATUS_EXPECTED(s);
1431	  }
1432	
1433	  // TODO: The granularity of the write_lock is too coarse.
1434	  std::lock_guard write_lock(write_mtx_);
1435	
1436	  WriteResults results;
1437	  // validate write batch size
1438	  if (docs.size() > kMaxWriteBatchSize) {
1439	    CHECK_RETURN_STATUS_EXPECTED(Status::InvalidArgument(
1440	        "Too many docs: ", docs.size(), " exceeds max write batch size of ",
1441	        kMaxWriteBatchSize));
1442	  }
1443	
1444	  for (auto &&doc : docs) {
1445	    if (need_switch_to_new_segment()) {
1446	      auto s = switch_to_new_segment_for_writing();
1447	      CHECK_RETURN_STATUS_EXPECTED(s);
1448	    }
1449	
1450	    Status s;
1451	
1452	    switch (mode) {
1453	      case WriteMode::UPSERT:
1454	        s = handle_upsert(doc);
1455	        break;
1456	      case WriteMode::UPDATE:
1457	        s = handle_update(doc);
1458	        break;
1459	      case WriteMode::INSERT:
1460	        s = handle_insert(doc);
1461	        break;
1462	      default:
1463	        s = Status::InvalidArgument("Invalid write mode");
1464	    }
1465	
1466	    results.push_back(s);
1467	  }
1468	
1469	  return results;
1470	}
