1472	bool CollectionImpl::need_switch_to_new_segment() const {
1473	  return writing_segment_->doc_count() >= schema_->max_doc_count_per_segment();
1474	}
1475	
1476	Status CollectionImpl::commit_schema_change_with_new_writing_segment(
1477	    const CollectionSchema::Ptr &new_schema,
1478	    const Segment::Ptr &old_writing_segment, const Version &old_version,
1479	    Version *new_version, uint64_t writing_min_doc_id) {
1480	  if (new_version == nullptr) {
1481	    return Status::InvalidArgument("new_version is null");
1482	  }
1483	
1484	  auto seg_options =
1485	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_};
1486	  auto new_writing_segment = Segment::CreateAndOpen(
1487	      path_, *new_schema, allocate_segment_id(), writing_min_doc_id, id_map_,
1488	      delete_store_, version_manager_, seg_options);
1489	  if (!new_writing_segment) {
1490	    return new_writing_segment.error();
1491	  }
1492	  new_version->reset_writing_segment_meta(new_writing_segment.value()->meta());
1493	  new_version->set_next_segment_id(segment_id_allocator_.load());
1494	
1495	  auto s = version_manager_->apply(*new_version);
1496	  if (!s.ok()) {
1497	    new_writing_segment.value()->destroy();
1498	    return s;
1499	  }
1500	
1501	  s = version_manager_->flush();
1502	  if (!s.ok()) {
1503	    new_writing_segment.value()->destroy();
1504	    auto rollback_status = version_manager_->apply(old_version);
1505	    CHECK_RETURN_STATUS(rollback_status);
1506	    return s;
1507	  }
1508	
1509	  schema_ = new_schema;
1510	  writing_segment_ = new_writing_segment.value();
1511	  s = old_writing_segment->destroy();
1512	  CHECK_RETURN_STATUS(s);
1513	
1514	  return Status::OK();
1515	}
1516	
1517	Status CollectionImpl::switch_to_new_segment_for_writing(
1518	    const CollectionSchema::Ptr &schema) {
1519	  auto s = writing_segment_->dump();
1520	  CHECK_RETURN_STATUS(s);
1521	
1522	  s = segment_manager_->add_segment(writing_segment_);
1523	  CHECK_RETURN_STATUS(s);
1524	
1525	  // when create new segment, segment meta should create a first new block
1526	  // meta
1527	  auto new_segment = Segment::CreateAndOpen(
1528	      path_, schema == nullptr ? *schema_ : *schema, allocate_segment_id(),
1529	      writing_segment_->meta()->max_doc_id() + 1, id_map_, delete_store_,
1530	      version_manager_,
1531	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_});
1532	  if (!new_segment) {
1533	    return new_segment.error();
1534	  }
1535	
1536	  Version version = version_manager_->get_current_version();
1537	  auto writing_segment_meta = writing_segment_->meta();
1538	  writing_segment_meta->remove_writing_forward_block();
1539	  s = version.add_persisted_segment_meta(writing_segment_meta);
1540	  CHECK_RETURN_STATUS(s);
1541	
1542	  writing_segment_ = new_segment.value();
1543	  version.reset_writing_segment_meta(writing_segment_->meta());
1544	  version.set_next_segment_id(segment_id_allocator_.load());
1545	
1546	  s = version_manager_->apply(version);
1547	  CHECK_RETURN_STATUS(s);
1548	  s = version_manager_->flush();
1549	  CHECK_RETURN_STATUS(s);
1550	
1551	  return Status::OK();
1552	}
