1554	Result<WriteResults> CollectionImpl::Delete(
1555	    const std::vector<std::string> &pks) {
1556	  CHECK_READONLY_RETURN_STATUS_EXPECTED();
1557	
1558	  std::shared_lock lock(schema_handle_mtx_);
1559	
1560	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1561	
1562	  // TODO: The granularity of the write_lock is too coarse.
1563	  std::lock_guard write_lock(write_mtx_);
1564	  WriteResults results;
1565	  for (auto &&pk : pks) {
1566	    Status s = writing_segment_->Delete(pk);
1567	    results.push_back(s);
1568	  }
1569	
1570	  return results;
1571	}
