1573	Status CollectionImpl::DeleteByFilter(const std::string &filter) {
1574	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
1575	
1576	  std::shared_lock lock(schema_handle_mtx_);
1577	
1578	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
1579	
1580	  SearchQuery query;
1581	  query.filter_ = filter;
1582	  query.topk_ = INT32_MAX;
1583	  query.output_fields_ = std::vector<std::string>{};
1584	  query.include_doc_id_ = true;
1585	
1586	  auto ret =
1587	      sql_engine_->execute(schema_, std::move(query), get_all_segments());
1588	  if (!ret.has_value()) {
1589	    return ret.error();
1590	  }
1591	
1592	  // TODO: The granularity of the write_lock is too coarse.
1593	  std::lock_guard write_lock(write_mtx_);
1594	  for (auto &doc : ret.value()) {
1595	    Status s = writing_segment_->Delete(doc->doc_id());
1596	    if (!s.ok()) {
1597	      LOG_ERROR("Delete doc_id: %zu failed", (size_t)doc->doc_id());
