  pid_t pid = fork();
  ASSERT_GE(pid, 0);

  if (pid == 0) {
    char arg_path[] = "--path";
    char *args[] = {const_cast<char *>(optimizer_bin_.c_str()), arg_path,
                    const_cast<char *>(path.c_str()), nullptr};
